fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    a.into_iter()
        .map(|s| {
            let mut lines = Vec::new();
            let bytes = s.as_bytes();
            let mut start = 0;
            let len = bytes.len();

            for i in 0..len {
                if bytes[i] == b'\n' {
                    // Found a line ending
                    let end = if i > 0 && bytes[i - 1] == b'\r' {
                        // \r\n line ending
                        if keepends {
                            i + 1
                        } else {
                            i - 1
                        }
                    } else {
                        // \n line ending only
                        if keepends {
                            i + 1
                        } else {
                            i
                        }
                    };
                    lines.push(s[start..end].to_string());
                    start = i + 1;
                }
            }
            // Add last line slice if any remaining characters after last line break
            if start < len {
                lines.push(s[start..].to_string());
            }

            // If no line ending was found, lines would be empty; produce non-empty output
            if lines.is_empty() {
                lines.push(s);
            }

            lines
        })
        .collect()
}